export function validPalindromeRecursive(s: string): boolean {
  function check(left: number, right: number, used: boolean): boolean {
    while (left < right) {
      if (s[left] === s[right]) {
        left += 1;
        right -= 1;
      } else if (!used) {
        return check(left + 1, right, true) || check(left, right - 1, true);
      } else {
        return false;
      }
    }
    return true;
  }
  return check(0, s.length - 1, false);
}

