type TreeNode = { val: number; left?: TreeNode | null; right?: TreeNode | null };
export function verticalOrder(root: TreeNode | null): number[][] {
  if (!root) return [];
  const cols = new Map<number, number[]>();
  const queue: Array<[TreeNode, number]> = [[root, 0]];
  for (let i = 0; i < queue.length; i += 1) {
    const [node, col] = queue[i];
    cols.set(col, [...(cols.get(col) ?? []), node.val]);
    if (node.left) queue.push([node.left, col - 1]);
    if (node.right) queue.push([node.right, col + 1]);
  }
  return [...cols.keys()].sort((a, b) => a - b).map((col) => cols.get(col)!);
}

