List<List<Integer>> verticalOrder(TreeNode root) {
  if (root == null) return List.of();
  Map<Integer, List<Integer>> cols = new HashMap<>();
  Queue<Object[]> queue = new ArrayDeque<>();
  queue.add(new Object[] { root, 0 });
  while (!queue.isEmpty()) {
    Object[] item = queue.remove();
    TreeNode node = (TreeNode) item[0];
    int col = (Integer) item[1];
    cols.computeIfAbsent(col, k -> new ArrayList<>()).add(node.val);
    if (node.left != null) queue.add(new Object[] { node.left, col - 1 });
    if (node.right != null) queue.add(new Object[] { node.right, col + 1 });
  }
  return cols.keySet().stream().sorted().map(cols::get).toList();
}

