type TreeNode = { val: number; left?: TreeNode | null; right?: TreeNode | null };
export function verticalTraversal(root: TreeNode | null): number[][] {
  const rows: Array<[number, number, number]> = [];
  function dfs(node: TreeNode | null, row: number, col: number): void {
    if (!node) return;
    rows.push([col, row, node.val]);
    dfs(node.left ?? null, row + 1, col - 1);
    dfs(node.right ?? null, row + 1, col + 1);
  }
  dfs(root, 0, 0);
  rows.sort((a, b) => a[0] - b[0] || a[1] - b[1] || a[2] - b[2]);
  const out: number[][] = [];
  let lastCol: number | undefined;
  for (const [col, , value] of rows) {
    if (lastCol === undefined || col !== lastCol) {
      out.push([]);
      lastCol = col;
    }
    out[out.length - 1].push(value);
  }
  return out;
}

