List<List<Integer>> verticalTraversal(TreeNode root) {
  List<int[]> rows = new ArrayList<>();
  dfs(root, 0, 0, rows);
  rows.sort((a, b) -> a[0] != b[0] ? a[0] - b[0] : a[1] != b[1] ? a[1] - b[1] : a[2] - b[2]);
  List<List<Integer>> out = new ArrayList<>();
  Integer lastCol = null;
  for (int[] row : rows) {
    if (lastCol == null || row[0] != lastCol) {
      out.add(new ArrayList<>());
      lastCol = row[0];
    }
    out.get(out.size() - 1).add(row[2]);
  }
  return out;
}
void dfs(TreeNode node, int row, int col, List<int[]> rows) {
  if (node == null) return;
  rows.add(new int[] { col, row, node.val });
  dfs(node.left, row + 1, col - 1, rows);
  dfs(node.right, row + 1, col + 1, rows);
}

