export function cleanParenthesesTwoPass(s: string): string {
  const first: string[] = [];
  let balance = 0;
  for (const ch of s) {
    if (ch === '(') { balance += 1; first.push(ch); }
    else if (ch === ')') {
      if (balance === 0) continue;
      balance -= 1;
      first.push(ch);
    } else first.push(ch);
  }
  const out: string[] = [];
  for (let i = first.length - 1; i >= 0; i -= 1) {
    if (first[i] === '(' && balance > 0) {
      balance -= 1;
      continue;
    }
    out.push(first[i]);
  }
  return out.reverse().join('');
}

